local ButterDishMaker = {}
local PRODUCTS = {
    iron_butterdish = { name = "Železni posodica za maslo", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni posodica za maslo za kuharje." },
    bronze_butterdish = { name = "Bronast posodica za maslo", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast posodica za maslo za kuharje." },
    silver_butterdish = { name = "Srebrn posodica za maslo", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn posodica za maslo za kuharje." },
    gilded_butterdish = { name = "Pozlačen posodica za maslo", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen posodica za maslo za kuharje." },
    jewel_set_butterdish = { name = "Draguljast posodica za maslo", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast posodica za maslo za kuharje." },
    royal_sovereign_butterdish = { name = "Kraljevski suveren posodica za maslo", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren posodica za maslo z biseri za krono." },
}
local BUILDINGS = {
    butterdish_workshop = { name = "Butterdish delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    butterdish_house = { name = "Butterdish hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_butterdish_atelier = { name = "Mojstrski butterdish atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_butterdish_palace = { name = "Suverena butterdish palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
ButterDishMaker.ironStock=12; ButterDishMaker.bronzeStock=10; ButterDishMaker.woodStock=14; ButterDishMaker.leatherStock=10; ButterDishMaker.silverStock=8; ButterDishMaker.goldStock=6; ButterDishMaker.jewelStock=4; ButterDishMaker.pearlStock=4
ButterDishMaker.productStock = {}; ButterDishMaker.buildings = {}; ButterDishMaker.maker = nil; ButterDishMaker.activeMaking = {}; ButterDishMaker.totalProducts = 0; ButterDishMaker.dayTimer = 0
function ButterDishMaker.init() ButterDishMaker.ironStock=12; ButterDishMaker.bronzeStock=10; ButterDishMaker.woodStock=14; ButterDishMaker.leatherStock=10; ButterDishMaker.silverStock=8; ButterDishMaker.goldStock=6; ButterDishMaker.jewelStock=4; ButterDishMaker.pearlStock=4; ButterDishMaker.productStock={}; ButterDishMaker.buildings={}; ButterDishMaker.maker=nil; ButterDishMaker.activeMaking={}; ButterDishMaker.totalProducts=0; ButterDishMaker.dayTimer=0; print("[ButterDishMaker] Royal Butter Dish Maker System initialized (6 products, 4 buildings)") end
function ButterDishMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ButterDishMaker.maker={name=n or ("Posodičar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Posodičar najet: %s (spretnost: %d)",ButterDishMaker.maker.name,s),"success") end; return true end
function ButterDishMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ButterDishMaker.build(id) local ok,e=ButterDishMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ButterDishMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ButterDishMaker.getQualityBonus() local b=0; for _,bd in ipairs(ButterDishMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ButterDishMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and ButterDishMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and ButterDishMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and ButterDishMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and ButterDishMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and ButterDishMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ButterDishMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and ButterDishMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and ButterDishMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #ButterDishMaker.buildings==0 then return false,"Potrebna posodična delavnica" end; if not ButterDishMaker.maker then return false,"Potreben posodičar" end; return true end
function ButterDishMaker.make(pt,qty) qty=qty or 1; local ok,e=ButterDishMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then ButterDishMaker.ironStock=ButterDishMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then ButterDishMaker.bronzeStock=ButterDishMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then ButterDishMaker.woodStock=ButterDishMaker.woodStock-d.woodCost*qty end; if d.leatherCost then ButterDishMaker.leatherStock=ButterDishMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then ButterDishMaker.silverStock=ButterDishMaker.silverStock-d.silverCost*qty end; if d.goldCost then ButterDishMaker.goldStock=ButterDishMaker.goldStock-d.goldCost*qty end; if d.jewelCost then ButterDishMaker.jewelStock=ButterDishMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then ButterDishMaker.pearlStock=ButterDishMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if ButterDishMaker.maker then t=math.max(1,t-math.floor(ButterDishMaker.maker.skill/13)) end; table.insert(ButterDishMaker.activeMaking,{id="butterdish_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ButterDishMaker.completeMaking(m) local q=1.0+(ButterDishMaker.getQualityBonus()/100); if ButterDishMaker.maker then q=q+(ButterDishMaker.maker.skill/140) end; q=math.min(2.5,q); ButterDishMaker.productStock[m.productType]=(ButterDishMaker.productStock[m.productType] or 0)+m.quantity; ButterDishMaker.totalProducts=ButterDishMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ButterDishMaker.maker then ButterDishMaker.maker.itemsMade=ButterDishMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then ButterDishMaker.maker.skill=math.min(100,ButterDishMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Posodica izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"butterdish.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function ButterDishMaker.update(dt) if not _G.state then return end; ButterDishMaker.dayTimer=ButterDishMaker.dayTimer+dt; if ButterDishMaker.dayTimer>=30 then ButterDishMaker.dayTimer=0; for i=#ButterDishMaker.activeMaking,1,-1 do local m=ButterDishMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ButterDishMaker.completeMaking(m); table.remove(ButterDishMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ButterDishMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ButterDishMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ButterDishMaker.getStats() return {ironStock=ButterDishMaker.ironStock,bronzeStock=ButterDishMaker.bronzeStock,woodStock=ButterDishMaker.woodStock,leatherStock=ButterDishMaker.leatherStock,silverStock=ButterDishMaker.silverStock,goldStock=ButterDishMaker.goldStock,jewelStock=ButterDishMaker.jewelStock,pearlStock=ButterDishMaker.pearlStock,productStock=ButterDishMaker.productStock,numBuildings=#ButterDishMaker.buildings,hasMaker=ButterDishMaker.maker~=nil,makerName=ButterDishMaker.maker and ButterDishMaker.maker.name or "—",makerSkill=ButterDishMaker.maker and ButterDishMaker.maker.skill or 0,activeMaking=#ButterDishMaker.activeMaking,totalProducts=ButterDishMaker.totalProducts} end
return ButterDishMaker
